INSERT INTO `wp_posts` VALUES (1,1,'2026-09-16 03:21:57','2026-09-16 03:21:57','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','publish','open','open','','hello-world','','','2026-09-16 03:21:57','2026-09-16 03:21:57','',0,'http://wordpress.local:8081/?p=1',0,'post','',4),(2,1,'2026-09-16 03:21:57','2026-09-16 03:21:57','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://wordpress.local:8081/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','publish','closed','open','','sample-page','','','2026-09-16 03:21:57','2026-09-16 03:21:57','',0,'http://wordpress.local:8081/?page_id=2',0,'page','',0),(3,1,'2026-09-16 03:21:57','2026-09-16 03:21:57','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://wordpress.local:8081.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy Policy','','draft','closed','open','','privacy-policy','','','2026-09-16 03:21:57','2026-09-16 03:21:57','',0,'http://wordpress.local:8081/?page_id=3',0,'page','',0),(5,0,'2026-09-17 05:39:35','2026-09-17 05:39:35','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-09-17 05:39:35','2026-09-17 05:39:35','',0,'http://wordpress.local:8081/?p=5',0,'wp_navigation','',0),(6,1,'2026-09-17 07:32:27','2026-09-17 07:32:27','Trí tuệ nhân tạo đang được ứng dụng trong nhiều lĩnh vực nghiên cứu khoa học, từ phân tích dữ liệu, mô phỏng đến hỗ trợ các phát minh mới. Công nghệ này giúp tối ưu hóa thời gian và gia tăng độ chính xác trong các nghiên cứu phức tạp.','Trí tuệ nhân tạo đang thay đổi cách con người nghiên cứu khoa học','Trí tuệ nhân tạo (AI) giúp tăng tốc độ phát hiện thuốc mới, dự đoán cấu trúc protein và tối ưu hóa các thí nghiệm phức tạp.','publish','open','open','','tri-tue-nhan-tao-dang-thay-doi-cach-con-nguoi-nghien-cuu-khoa-hoc','','','2026-09-23 01:20:11','2026-09-23 01:20:11','',0,'http://wordpress.local:8081/?p=6',0,'post','',4),(7,1,'2026-09-17 07:25:00','2026-09-17 07:25:00','{\"version\": 3, \"isGlobalStylesUserThemeJSON\": true }','Custom Styles','','publish','closed','closed','','wp-global-styles-twentytwentyfive','','','2026-09-17 07:25:00','2026-09-17 07:25:00','',0,'http://wordpress.local:8081/?p=7',0,'wp_global_styles','',0),(8,1,'2026-09-17 07:30:22','2026-09-17 07:30:22','','AI6','','inherit','open','closed','','ai6','','','2026-09-17 07:30:22','2026-09-17 07:30:22','',6,'http://wordpress.local:8081/wp-content/uploads/2026/09/AI6.jpg',0,'attachment','image/jpeg',0),(9,1,'2026-09-17 07:32:27','2026-09-17 07:32:27','<!-- wp:paragraph -->\n<p><strong>Trí tuệ nhân tạo (AI)</strong> đang trở thành một công cụ hỗ trợ quan trọng trong nhiều lĩnh vực nghiên cứu khoa học. Khả năng xử lý lượng lớn dữ liệu trong thời gian ngắn giúp AI hỗ trợ các nhà nghiên cứu tìm kiếm quy luật và mối liên hệ mà phương pháp truyền thống có thể mất nhiều thời gian để phát hiện.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://cdn.thuvienphapluat.vn/uploads/tintuc/2025/07/17/khoa-hoc-la-gi.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Trong lĩnh vực <strong>sinh học và y sinh</strong>, các mô hình AI có thể được sử dụng để phân tích dữ liệu sinh học, hỗ trợ nghiên cứu protein và tìm kiếm những hướng tiếp cận mới trong quá trình phát triển thuốc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Trong <strong>vật lý và thiên văn học</strong>, AI cũng có thể hỗ trợ phân tích hình ảnh từ kính thiên văn, xử lý dữ liệu từ các thí nghiệm và nhận diện những hiện tượng cần được nghiên cứu sâu hơn.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Một ưu điểm khác của AI là khả năng hỗ trợ <strong>mô phỏng và dự đoán</strong>. Các nhà khoa học có thể sử dụng mô hình tính toán để thử nghiệm nhiều kịch bản trước khi tiến hành thí nghiệm thực tế, từ đó tiết kiệm thời gian và nguồn lực.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Tuy nhiên, AI không thay thế hoàn toàn vai trò của nhà khoa học. Kết quả do AI tạo ra vẫn cần được kiểm tra, đánh giá và xác nhận bằng phương pháp khoa học. Chất lượng dữ liệu đầu vào và cách xây dựng mô hình cũng có ảnh hưởng lớn đến kết quả.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Trong tương lai, sự kết hợp giữa <strong>kiến thức chuyên môn của con người và khả năng xử lý dữ liệu của AI</strong> có thể tiếp tục mở rộng các phương pháp nghiên cứu và tạo ra thêm nhiều hướng tiếp cận mới trong khoa học.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Trí tuệ nhân tạo đang thay đổi cách con người nghiên cứu khoa học','Trí tuệ nhân tạo đang được ứng dụng trong nhiều lĩnh vực nghiên cứu khoa học, từ phân tích dữ liệu, mô phỏng đến hỗ trợ phát hiện các xu hướng mới, giúp các nhà khoa học tiết kiệm thời gian và mở rộng phương pháp nghiên cứu.','inherit','closed','closed','','6-revision-v1','','','2026-09-17 07:32:27','2026-09-17 07:32:27','',6,'http://wordpress.local:8081/?p=9',0,'revision','',0),(10,1,'2026-09-17 07:34:53','2026-09-17 07:34:53','<!-- wp:paragraph -->\n<p><strong>Đời sống chính trị</strong> có ảnh hưởng đến nhiều mặt của xã hội, từ việc xây dựng chính sách, tổ chức bộ máy nhà nước đến việc giải quyết các vấn đề liên quan đến cộng đồng.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://bcp.cdnchinhphu.vn/334894974524682240/2022/9/16/csxh-1663321469738598022903.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Người dân có thể tham gia vào đời sống chính trị thông qua nhiều hình thức khác nhau, trong đó có việc tìm hiểu thông tin, tham gia các hoạt động cộng đồng, đóng góp ý kiến và thực hiện các quyền và nghĩa vụ theo quy định của pháp luật.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Một yếu tố quan trọng là <strong>tiếp cận thông tin chính xác</strong>. Khi có nhiều nguồn thông tin khác nhau, người dân cần xem xét nguồn cung cấp, thời điểm công bố và bối cảnh của thông tin trước khi đưa ra nhận định.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Các cơ quan nhà nước cũng có vai trò trong việc cung cấp thông tin và giải thích chính sách để người dân có cơ sở tìm hiểu và tham gia vào các vấn đề chung của xã hội.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Bên cạnh đó, việc <strong>lắng nghe ý kiến của cộng đồng</strong> có thể giúp các cơ quan quản lý nhận diện những vấn đề phát sinh trong thực tế. Những ý kiến này có thể trở thành nguồn thông tin tham khảo trong quá trình xây dựng và thực hiện chính sách.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Đời sống chính trị vì vậy không chỉ liên quan đến các cơ quan nhà nước hay các tổ chức chính trị mà còn có sự tham gia của nhiều thành phần trong xã hội. Việc mỗi cá nhân chủ động tìm hiểu thông tin, tôn trọng pháp luật và tham gia các hoạt động cộng đồng góp phần tạo nên một môi trường xã hội có sự trao đổi và tham gia rộng rãi.</p>\n<!-- /wp:paragraph -->','Vai trò của người dân trong đời sống chính trị và quản lý xã hội','Người dân có thể tham gia vào đời sống chính trị thông qua việc tìm hiểu thông tin, đóng góp ý kiến, tham gia các hoạt động cộng đồng và thực hiện các quyền, nghĩa vụ theo quy định của pháp luật.','publish','open','open','','vai-tro-cua-nguoi-dan-trong-doi-song-chinh-tri-va-quan-ly-xa-hoi','','','2026-09-17 07:34:53','2026-09-17 07:34:53','',0,'http://wordpress.local:8081/?p=10',0,'post','',4),(11,1,'2026-09-17 07:34:53','2026-09-17 07:34:53','<!-- wp:paragraph -->\n<p><strong>Đời sống chính trị</strong> có ảnh hưởng đến nhiều mặt của xã hội, từ việc xây dựng chính sách, tổ chức bộ máy nhà nước đến việc giải quyết các vấn đề liên quan đến cộng đồng.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://bcp.cdnchinhphu.vn/334894974524682240/2022/9/16/csxh-1663321469738598022903.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Người dân có thể tham gia vào đời sống chính trị thông qua nhiều hình thức khác nhau, trong đó có việc tìm hiểu thông tin, tham gia các hoạt động cộng đồng, đóng góp ý kiến và thực hiện các quyền và nghĩa vụ theo quy định của pháp luật.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Một yếu tố quan trọng là <strong>tiếp cận thông tin chính xác</strong>. Khi có nhiều nguồn thông tin khác nhau, người dân cần xem xét nguồn cung cấp, thời điểm công bố và bối cảnh của thông tin trước khi đưa ra nhận định.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Các cơ quan nhà nước cũng có vai trò trong việc cung cấp thông tin và giải thích chính sách để người dân có cơ sở tìm hiểu và tham gia vào các vấn đề chung của xã hội.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Bên cạnh đó, việc <strong>lắng nghe ý kiến của cộng đồng</strong> có thể giúp các cơ quan quản lý nhận diện những vấn đề phát sinh trong thực tế. Những ý kiến này có thể trở thành nguồn thông tin tham khảo trong quá trình xây dựng và thực hiện chính sách.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Đời sống chính trị vì vậy không chỉ liên quan đến các cơ quan nhà nước hay các tổ chức chính trị mà còn có sự tham gia của nhiều thành phần trong xã hội. Việc mỗi cá nhân chủ động tìm hiểu thông tin, tôn trọng pháp luật và tham gia các hoạt động cộng đồng góp phần tạo nên một môi trường xã hội có sự trao đổi và tham gia rộng rãi.</p>\n<!-- /wp:paragraph -->','Vai trò của người dân trong đời sống chính trị và quản lý xã hội','Người dân có thể tham gia vào đời sống chính trị thông qua việc tìm hiểu thông tin, đóng góp ý kiến, tham gia các hoạt động cộng đồng và thực hiện các quyền, nghĩa vụ theo quy định của pháp luật.','inherit','closed','closed','','10-revision-v1','','','2026-09-17 07:34:53','2026-09-17 07:34:53','',10,'http://wordpress.local:8081/?p=11',0,'revision','',0),(12,1,'2026-09-23 00:22:34','2026-09-23 00:22:34','<!-- wp:paragraph -->\n<p><strong>Đời sống chính trị</strong> có ảnh hưởng đến nhiều mặt của xã hội, từ việc xây dựng chính sách, tổ chức bộ máy nhà nước đến việc giải quyết các vấn đề liên quan đến cộng đồng.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://bcp.cdnchinhphu.vn/334894974524682240/2022/9/16/csxh-1663321469738598022903.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Người dân có thể tham gia vào đời sống chính trị thông qua nhiều hình thức khác nhau, trong đó có việc tìm hiểu thông tin, tham gia các hoạt động cộng đồng, đóng góp ý kiến và thực hiện các quyền và nghĩa vụ theo quy định của pháp luật.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Một yếu tố quan trọng là <strong>tiếp cận thông tin chính xác</strong>. Khi có nhiều nguồn thông tin khác nhau, người dân cần xem xét nguồn cung cấp, thời điểm công bố và bối cảnh của thông tin trước khi đưa ra nhận định.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Các cơ quan nhà nước cũng có vai trò trong việc cung cấp thông tin và giải thích chính sách để người dân có cơ sở tìm hiểu và tham gia vào các vấn đề chung của xã hội.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Bên cạnh đó, việc <strong>lắng nghe ý kiến của cộng đồng</strong> có thể giúp các cơ quan quản lý nhận diện những vấn đề phát sinh trong thực tế. Những ý kiến này có thể trở thành nguồn thông tin tham khảo trong quá trình xây dựng và thực hiện chính sách.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Đời sống chính trị vì vậy không chỉ liên quan đến các cơ quan nhà nước hay các tổ chức chính trị mà còn có sự tham gia của nhiều thành phần trong xã hội. Việc mỗi cá nhân chủ động tìm hiểu thông tin, tôn trọng pháp luật và tham gia các hoạt động cộng đồng góp phần tạo nên một môi trường xã hội có sự trao đổi và tham gia rộng rãi.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Vai trò của người dân trong đời sống chính trị và quản lý xã hội','Người dân có thể tham gia vào đời sống chính trị thông qua việc tìm hiểu thông tin, đóng góp ý kiến, tham gia các hoạt động cộng đồng và thực hiện các quyền, nghĩa vụ theo quy định của pháp luật.','inherit','closed','closed','','10-autosave-v1','','','2026-09-23 00:22:34','2026-09-23 00:22:34','',10,'http://wordpress.local/?p=12',0,'revision','',0),(13,0,'2026-09-23 01:06:32','2026-09-23 01:06:32','<p style=\"text-align:center; margin: 25px 0;\"><img src=\"http://wordpress.local/wp-content/uploads/2026/09/kinh_te_phat_trien.svg\" alt=\"Chính sách phát triển kinh tế xã hội giai đoạn mới\" class=\"aligncenter size-full\" style=\"max-width:100%; height:auto; border-radius:12px; box-shadow:0 8px 24px rgba(0,0,0,0.12);\" /></p>\nNội dung chi tiết về các định hướng chính sách phát triển kinh tế xã hội giai đoạn mới, tăng cường cải cách hành chính và đổi mới tư duy quản lý.','Chính sách phát triển kinh tế xã hội giai đoạn mới','Các định hướng chính sách phát triển kinh tế xã hội giai đoạn mới và cải cách hành chính.','publish','open','open','','chinh-sach-phat-trien-kinh-te-xa-hoi-giai-doan-moi','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',0,'http://wordpress.local/?p=13',0,'post','',4),(14,0,'2026-09-23 01:06:32','2026-09-23 01:06:32','<p style=\"text-align:center; margin: 25px 0;\"><img src=\"http://wordpress.local/wp-content/uploads/2026/09/quan_ly_do_thi.svg\" alt=\"Đổi mới công tác quản lý đô thị và hạ tầng giao thông\" class=\"aligncenter size-full\" style=\"max-width:100%; height:auto; border-radius:12px; box-shadow:0 8px 24px rgba(0,0,0,0.12);\" /></p>\nCông tác quản lý đô thị và phát triển hạ tầng giao thông trọng điểm đang được triển khai đồng bộ tại các thành phố lớn.','Đổi mới công tác quản lý đô thị và hạ tầng giao thông','Công tác quản lý đô thị và phát triển hạ tầng giao thông trọng điểm được triển khai đồng bộ.','publish','open','open','','doi-moi-cong-tac-quan-ly-do-thi-va-ha-tang-giao-thong','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',0,'http://wordpress.local/?p=14',0,'post','',4),(15,0,'2026-09-23 01:06:32','2026-09-23 01:06:32','<p style=\"text-align:center; margin: 25px 0;\"><img src=\"http://wordpress.local/wp-content/uploads/2026/09/hop_tac_quoc_te.svg\" alt=\"Tăng cường hợp tác quốc tế và ngoại giao đa phương\" class=\"aligncenter size-full\" style=\"max-width:100%; height:auto; border-radius:12px; box-shadow:0 8px 24px rgba(0,0,0,0.12);\" /></p>\nNgoại giao đa phương và hợp tác quốc tế đóng vai trò quan trọng trong việc nâng cao vị thế đất nước trên trường quốc tế.','Tăng cường hợp tác quốc tế và ngoại giao đa phương','Ngoại giao đa phương và hợp tác quốc tế nâng cao vị thế quốc gia.','publish','open','open','','tang-cuong-hop-tac-quoc-te-va-ngoai-giao-da-phuong','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',0,'http://wordpress.local/?p=15',0,'post','',4),(16,0,'2026-09-23 01:06:32','2026-09-23 01:06:32','<p style=\"text-align:center; margin: 25px 0;\"><img src=\"http://wordpress.local/wp-content/uploads/2026/09/nang_luong_xanh.svg\" alt=\"Ứng dụng công nghệ năng lượng xanh và pin thế hệ mới\" class=\"aligncenter size-full\" style=\"max-width:100%; height:auto; border-radius:12px; box-shadow:0 8px 24px rgba(0,0,0,0.12);\" /></p>\nNghiên cứu mới về công nghệ lưu trữ năng lượng mặt trời và pin thế hệ mới giúp giảm chi phí và bảo vệ môi trường.','Ứng dụng công nghệ năng lượng xanh và pin thế hệ mới','Công nghệ lưu trữ năng lượng xanh và pin thế hệ mới bảo vệ môi trường.','publish','open','open','','ung-dung-cong-nghe-nang-luong-xanh-va-pin-the-he-moi','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',0,'http://wordpress.local/?p=16',0,'post','',4),(17,0,'2026-09-23 01:06:32','2026-09-23 01:06:32','<p style=\"text-align:center; margin: 25px 0;\"><img src=\"http://wordpress.local/wp-content/uploads/2026/09/kham_pha_vu_tru.svg\" alt=\"Khám phá mới về vũ trụ và sóng hấp dẫn\" class=\"aligncenter size-full\" style=\"max-width:100%; height:auto; border-radius:12px; box-shadow:0 8px 24px rgba(0,0,0,0.12);\" /></p>\nCác nhà thiên văn học vừa công bố phát hiện mới về sóng hấp dẫn và các thiên hà xa xôi trong vũ trụ.','Khám phá mới về vũ trụ và sóng hấp dẫn','Phát hiện mới về sóng hấp dẫn và sự hình thành các thiên hà.','publish','open','open','','kham-pha-moi-ve-vu-tru-va-song-hap-dan','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',0,'http://wordpress.local/?p=17',0,'post','',4),(18,0,'2026-09-23 01:06:32','2026-09-23 01:06:32','<p style=\"text-align:center; margin: 25px 0;\"><img src=\"http://wordpress.local/wp-content/uploads/2026/09/cong_nghe_sinh_hoc.svg\" alt=\"Đột phá trong công nghệ sinh học và y học tái tạo\" class=\"aligncenter size-full\" style=\"max-width:100%; height:auto; border-radius:12px; box-shadow:0 8px 24px rgba(0,0,0,0.12);\" /></p>\nCông nghệ chỉnh sửa gen và tế bào gốc đang mở ra nhiều triển vọng trong điều trị các bệnh mãn tính.','Đột phá trong công nghệ sinh học và y học tái tạo','Công nghệ chỉnh sửa gen mở ra triển vọng lớn trong y học tái tạo.','publish','open','open','','dot-pha-trong-cong-nghe-sinh-hoc-va-y-hoc-tai-tao','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',0,'http://wordpress.local/?p=18',0,'post','',4),(19,0,'2026-09-23 01:06:32','2026-09-23 01:06:32','<p style=\"text-align:center; margin: 25px 0;\"><img src=\"http://wordpress.local/wp-content/uploads/2026/09/thuong_mai_dien_tu.svg\" alt=\"Xu hướng thương mại điện tử và chuyển đổi số doanh nghiệp\" class=\"aligncenter size-full\" style=\"max-width:100%; height:auto; border-radius:12px; box-shadow:0 8px 24px rgba(0,0,0,0.12);\" /></p>\nThương mại điện tử tiếp tục tăng trưởng mạnh mẽ, thúc đẩy các doanh nghiệp truyền thống chuyển đổi số toàn diện.','Xu hướng thương mại điện tử và chuyển đổi số doanh nghiệp','Thương mại điện tử tăng trưởng bùng nổ thúc đẩy doanh nghiệp chuyển đổi số.','publish','open','open','','xu-huong-thuong-mai-dien-tu-va-chuyen-doi-so-doanh-nghiep','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',0,'http://wordpress.local/?p=19',0,'post','',3),(20,0,'2026-09-23 01:06:33','2026-09-23 01:06:33','<p style=\"text-align:center; margin: 25px 0;\"><img src=\"http://wordpress.local/wp-content/uploads/2026/09/tai_chinh_toan_cau.svg\" alt=\"Thị trường tài chính toàn cầu và các thách thức mới\" class=\"aligncenter size-full\" style=\"max-width:100%; height:auto; border-radius:12px; box-shadow:0 8px 24px rgba(0,0,0,0.12);\" /></p>\nPhân tích diễn biến thị trường tài chính, lãi suất ngân hàng và các giải pháp ổn định kinh tế vĩ mô.','Thị trường tài chính toàn cầu và các thách thức mới','Phân tích diễn biến thị trường tài chính và các chính sách kinh tế vĩ mô.','publish','open','open','','thi-truong-tai-chinh-toan-cau-va-cac-thach-thuc-moi','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',0,'http://wordpress.local/?p=20',0,'post','',3),(21,0,'2026-09-23 01:06:33','2026-09-23 01:06:33','<p style=\"text-align:center; margin: 25px 0;\"><img src=\"http://wordpress.local/wp-content/uploads/2026/09/kinh_te_tuan_hoan.svg\" alt=\"Phát triển kinh tế tuần hoàn và bền vững trong công nghiệp\" class=\"aligncenter size-full\" style=\"max-width:100%; height:auto; border-radius:12px; box-shadow:0 8px 24px rgba(0,0,0,0.12);\" /></p>\nMô hình kinh tế tuần hoàn giúp tối ưu hóa nguồn nguyên vật liệu và giảm thiểu chất thải công nghiệp.','Phát triển kinh tế tuần hoàn và bền vững trong công nghiệp','Mô hình kinh tế tuần hoàn tối ưu hóa nguồn lực và giảm chất thải.','publish','open','open','','phat-trien-kinh-te-tuan-hoan-va-ben-vung-trong-cong-nghiep','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',0,'http://wordpress.local/?p=21',0,'post','',3),(24,0,'2026-09-23 01:09:46','2026-09-23 01:09:46','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_1.jpg\" alt=\"Chính sách phát triển kinh tế xã hội giai đoạn mới và tầm nhìn chiến lược\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Trong bối cảnh hội nhập quốc tế ngày càng sâu rộng, việc hoạch định và thực thi các chính sách phát triển kinh tế xã hội giai đoạn mới đóng vai trò then chốt đối với sự phát triển bền vững của quốc gia.</p>\n<h2>1. Đột phá trong cải cách hành chính và tư duy quản lý</h2>\n<p>Chính phủ đã ban hành nhiều nghị quyết quan trọng nhằm tháo gỡ khó khăn cho doanh nghiệp, cắt giảm các thủ tục rườm rà và đẩy mạnh ứng dụng công nghệ thông tin trong cung cấp dịch vụ công trực tuyến. Việc chuyển đổi từ phương thức quản lý truyền thống sang quản trị hiện đại dựa trên dữ liệu đã giúp tiết kiệm hàng ngàn tỷ đồng và thời gian cho xã hội.</p>\n<h2>2. Phát triển nguồn nhân lực chất lượng cao</h2>\n<p>Nguồn nhân lực được xác định là động lực trung tâm của sự phát triển. Các chính sách ưu đãi đối với giáo dục, đào tạo nghề và thu hút nhân tài trong và ngoài nước đang được triển khai mạnh mẽ.</p>','Chính sách phát triển kinh tế xã hội giai đoạn mới và tầm nhìn chiến lược','Các định hướng chính sách phát triển kinh tế xã hội giai đoạn mới mang tính đột phá, trọng tâm cải cách hành chính và đổi mới mô hình tăng trưởng.','publish','open','open','','chinh-sach-phat-trien-kinh-te-xa-hoi-giai-doan-moi-va-tam-nhin-chien-luoc','','','2026-09-23 01:13:19','2026-09-23 01:13:19','',0,'http://wordpress.local/?p=24',0,'post','',4),(25,0,'2026-09-23 01:09:46','2026-09-23 01:09:46','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_2.jpg\" alt=\"Đổi mới công tác quản lý đô thị và quy hoạch hạ tầng giao thông hiện đại\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Quản lý đô thị và quy hoạch hạ tầng giao thông là một trong những nhiệm vụ trọng tâm được các cấp chính quyền đặc biệt quan tâm trong thời kỳ công nghiệp hóa, hiện đại hóa.</p>\n<h2>1. Xây dựng các đô thị thông minh</h2>\n<p>Ứng dụng công nghệ Internet of Things (IoT) và trí tuệ nhân tạo trong giám sát giao thông, quản lý năng lượng và xử lý rác thải đang trở thành chuẩn mực mới tại các đại đô thị. Hệ thống trung tâm điều hành thông minh giúp chính quyền phản ứng nhanh chóng với các sự cố đô thị.</p>\n<h2>2. Đầu tư mạng lưới giao thông công cộng hiện đại</h2>\n<p>Các dự án đường sắt đô thị, xe buýt điện thông minh và hệ thống cầu vượt kết nối liên vùng đang được tăng tốc hoàn thành. Điều này không chỉ giảm thiểu ùn tắc giao thông mà còn giảm lượng khí thải carbon phát thải ra môi trường.</p>','Đổi mới công tác quản lý đô thị và quy hoạch hạ tầng giao thông hiện đại','Tập trung phát triển các đô thị thông minh, kết nối mạng lưới giao thông công cộng đường sắt đô thị và giảm ùn tắc.','publish','open','open','','doi-moi-cong-tac-quan-ly-do-thi-va-quy-hoach-ha-tang-giao-thong-hien-dai','','','2026-09-23 01:13:21','2026-09-23 01:13:21','',0,'http://wordpress.local/?p=25',0,'post','',3),(26,0,'2026-09-23 01:09:46','2026-09-23 01:09:46','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_3.jpg\" alt=\"Tăng cường hợp tác quốc tế và chủ động hội nhập ngoại giao đa phương\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Công tác đối ngoại và hợp tác quốc tế ngày càng khẳng định vị thế và đóng góp tích cực vào công cuộc phát triển chung của đất nước.</p>\n<h2>1. Đa phương hóa, đa dạng hóa quan hệ quốc tế</h2>\n<p>Việc ký kết và thực thi hiệu quả các hiệp định thương mại tự do thế hệ mới (FTA) đã mở ra không gian phát triển rộng lớn cho hàng hóa và dịch vụ trong nước vươn ra thị trường toàn cầu.</p>\n<h2>2. Thu hút dòng vốn đầu tư nước ngoài có chọn lọc</h2>\n<p>Chính sách thu hút FDI chuyển dịch mạnh mẽ từ số lượng sang chất lượng, ưu tiên các dự án áp dụng công nghệ cao, thân thiện môi trường và có tính lan tỏa lớn đối với nền kinh tế nội địa.</p>','Tăng cường hợp tác quốc tế và chủ động hội nhập ngoại giao đa phương','Ngoại giao đa phương đóng vai trò cầu nối thúc đẩy thương mại quốc tế, thu hút dòng vốn đầu tư FDI và nâng cao uy tín quốc gia.','publish','open','open','','tang-cuong-hop-tac-quoc-te-va-chu-dong-hoi-nhap-ngoai-giao-da-phuong','','','2026-09-23 01:13:23','2026-09-23 01:13:23','',0,'http://wordpress.local/?p=26',0,'post','',4),(27,0,'2026-09-23 01:09:46','2026-09-23 01:09:46','\n<p class=\"sapo\">Sự bùng nổ của Trí tuệ Nhân tạo (AI) và Học máy (Machine Learning) đang tạo ra một cuộc cách mạng sâu sắc trong cách thức các nhà khoa học thực hiện nghiên cứu.</p>\n\n<p><img src=\"https://picsum.photos/seed/ai1/800/450\" alt=\"Trí tuệ nhân tạo\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n\n<h2>1. Tăng tốc phân tích dữ liệu siêu khổng lồ</h2>\n<p>Trước đây, việc phân tích hàng tỷ chuỗi ADN hoặc dữ liệu thiên văn học có thể mất hàng thập kỷ. Ngày nay, với các mô hình học sâu hiện đại, AI có thể xử lý và phát hiện ra các quy luật ẩn giấu chỉ trong vài giờ đồng hồ.</p>\n\n<h2>2. Dự đoán cấu trúc sinh học và phân tử</h2>\n<p>Các công cụ như AlphaFold đã giải quyết được thách thức 50 năm qua của sinh học hiện đại bằng cách dự đoán chính xác cấu trúc 3D của gần như tất cả các protein đã biết. Điều này giúp các nhà nghiên cứu dược phẩm phát triển các loại thuốc điều trị bệnh hiểm nghèo nhanh hơn bao giờ hết.</p>','Trí tuệ nhân tạo đang thay đổi cách con người nghiên cứu khoa học','Trí tuệ nhân tạo (AI) giúp tăng tốc độ phát hiện thuốc mới, dự đoán cấu trúc protein và tối ưu hóa các thí nghiệm phức tạp.','inherit','closed','closed','','6-revision-v1','','','2026-09-23 01:09:46','2026-09-23 01:09:46','',6,'http://wordpress.local/?p=27',0,'revision','',0),(28,0,'2026-09-23 01:09:46','2026-09-23 01:09:46','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_5.jpg\" alt=\"Ứng dụng công nghệ năng lượng xanh và giải pháp pin lưu trữ thế hệ mới\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Chuyển dịch sang năng lượng tái tạo là con đường duy nhất để loài người đối phó với biến đổi khí hậu toàn cầu.</p>\n<h2>1. Đột phá từ công nghệ pin thể rắn</h2>\n<p>Pin thể rắn thế hệ mới mang lại mật độ năng lượng cao gấp đôi so với pin Lithium-ion truyền thống, đồng thời rút ngắn thời gian sạc xuống còn vài phút và loại bỏ hoàn toàn nguy cơ cháy nổ.</p>\n<h2>2. Tích hợp hệ thống lưới điện thông minh</h2>\n<p>Nhờ vào các hệ thống pin lưu trữ quy mô lớn kết hợp với AI dự báo thời tiết, các trang trại điện gió và điện mặt trời có thể cung cấp nguồn điện ổn định 24/7 mà không bị gián đoạn.</p>','Ứng dụng công nghệ năng lượng xanh và giải pháp pin lưu trữ thế hệ mới','Công nghệ pin thể rắn và giải pháp tích trữ năng lượng mặt trời giúp giải bài toán biến đổi khí hậu.','publish','open','open','','ung-dung-cong-nghe-nang-luong-xanh-va-giai-phap-pin-luu-tru-the-he-moi','','','2026-09-23 01:13:27','2026-09-23 01:13:27','',0,'http://wordpress.local/?p=28',0,'post','',3),(29,0,'2026-09-23 01:09:46','2026-09-23 01:09:46','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_6.jpg\" alt=\"Khám phá mới về vũ trụ, lỗ đen và sóng hấp dẫn liên ngân hà\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Vũ trụ bao la luôn chứa đựng những bí ẩn thách thức trí tuệ con người, và những phát hiện gần đây đang viết lại sách giáo khoa vật lý thiên văn.</p>\n<h2>1. Mắt thần James Webb và những thiên hà cổ đại</h2>\n<p>Kính thiên văn James Webb đã quan sát được những ánh sáng cổ xưa nhất hành tinh từ 13.5 tỷ năm trước, giúp các nhà vật lý hiểu rõ hơn về giai đoạn khởi đầu của vũ trụ.</p>\n<h2>2. Đo lường sóng hấp dẫn từ các vụ va chạm lỗ đen</h2>\n<p>Các đài quan sát LIGO và Virgo tiếp tục ghi nhận hàng loạt tín hiệu sóng hấp dẫn – những gợn sóng trong không-thời gian sinh ra từ sự hợp nhất giữa các lỗ đen siêu nặng.</p>','Khám phá mới về vũ trụ, lỗ đen và sóng hấp dẫn liên ngân hà','Kính thiên văn không gian James Webb hé lộ những hình ảnh đầu tiên về các thiên hà cổ đại hình thành ngay sau Vụ Nổ Lớn Big Bang.','publish','open','open','','kham-pha-moi-ve-vu-tru-lo-den-va-song-hap-dan-lien-ngan-ha','','','2026-09-23 01:13:28','2026-09-23 01:13:28','',0,'http://wordpress.local/?p=29',0,'post','',3),(30,0,'2026-09-23 01:09:46','2026-09-23 01:09:46','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_7.jpg\" alt=\"Đột phá trong công nghệ sinh học y học tái tạo và chỉnh sửa gen CRISPR\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Y học tái tạo và công nghệ gen đang mở ra kỷ nguyên y học cá thể hóa, nơi căn bệnh được chữa trị dựa trên mã gen riêng của từng bệnh nhân.</p>\n<h2>1. Công nghệ CRISPR-Cas9 trong điều trị y học</h2>\n<p>Các thử nghiệm lâm sàng sử dụng kéo sinh học CRISPR để sửa đổi mã gen lỗi đã chữa khỏi thành công bệnh hồng cầu hình liềm và mở ra hy vọng diệt trừ tận gốc virus HIV.</p>\n<h2>2. In 3D sinh học và nội tạng nhân tạo</h2>\n<p>Công nghệ in 3D tế bào sống đang tiến gần hơn đến việc sản xuất các mô cơ tim, màng da và mạch máu nhân tạo phục vụ ghép tạng mà không bị thải ghép.</p>','Đột phá trong công nghệ sinh học y học tái tạo và chỉnh sửa gen CRISPR','Kỹ thuật chỉnh sửa gen chính xác cao đang thử nghiệm điều trị các bệnh di truyền và ung thư tận gốc.','publish','open','open','','dot-pha-trong-cong-nghe-sinh-hoc-y-hoc-tai-tao-va-chinh-sua-gen-crispr','','','2026-09-23 01:13:30','2026-09-23 01:13:30','',0,'http://wordpress.local/?p=30',0,'post','',4),(31,0,'2026-09-23 01:09:46','2026-09-23 01:09:46','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_8.jpg\" alt=\"Xu hướng thương mại điện tử xuyên biên giới và chuyển đổi số doanh nghiệp\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Thương mại điện tử không còn là xu hướng chốc lát mà đã trở thành trụ cột quan trọng của nền kinh tế số toàn cầu.</p>\n<h2>1. Sự lên ngôi của bán hàng Omni-channel</h2>\n<p>Khách hàng ngày nay đòi hỏi trải nghiệm mua sắm liền mạch từ trực tuyến đến trực tiếp. Các doanh nghiệp tiên phong đang áp dụng AI để cá nhân hóa đề xuất sản phẩm cho từng người dùng.</p>\n<h2>2. Logistics thông minh và tự động hóa kho hàng</h2>\n<p>Hệ thống tự động hóa kho bãi sử dụng robot giao hàng và thuật toán định tuyến thông minh giúp giao hàng trong ngày với chi phí thấp hơn 30%.</p>','Xu hướng thương mại điện tử xuyên biên giới và chuyển đổi số doanh nghiệp','Thương mại điện tử phát triển thần tốc thúc đẩy các chuỗi cung ứng tối ưu hóa bằng trí tuệ nhân tạo và dữ liệu lớn.','publish','open','open','','xu-huong-thuong-mai-dien-tu-xuyen-bien-gioi-va-chuyen-doi-so-doanh-nghiep','','','2026-09-23 01:13:32','2026-09-23 01:13:32','',0,'http://wordpress.local/?p=31',0,'post','',3),(32,0,'2026-09-23 01:09:46','2026-09-23 01:09:46','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_9.jpg\" alt=\"Thị trường tài chính toàn cầu, xu hướng lãi suất và các thách thức lớn\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Nền kinh tế thế giới đang trải qua giai đoạn biến động đầy thách thức với lạm phát, điều chỉnh chính sách lãi suất và sự dịch chuyển của các dòng vốn đầu tư.</p>\n<h2>1. Tác động từ chính sách tiền tệ thắt chặt</h2>\n<p>Các chính sách điều chỉnh lãi suất ngân hàng nhằm kiểm soát lạm phát đã ảnh hưởng đáng kể đến chi phí vốn của doanh nghiệp và hoạt động kinh doanh bất động sản.</p>\n<h2>2. Sự bùng nổ của tài chính công nghệ (Fintech)</h2>\n<p>Các ứng dụng thanh toán không tiền mặt, ngân hàng số và tài sản mã hóa đang thay đổi thói quen quản lý tài chính cá nhân của thế hệ trẻ.</p>','Thị trường tài chính toàn cầu, xu hướng lãi suất và các thách thức lớn','Phân tích biến động tỷ giá, chính sách tiền tệ của các Ngân hàng Trung ương lớn và định hướng đầu tư an toàn.','publish','open','open','','thi-truong-tai-chinh-toan-cau-xu-huong-lai-suat-va-cac-thach-thuc-lon','','','2026-09-23 01:13:34','2026-09-23 01:13:34','',0,'http://wordpress.local/?p=32',0,'post','',4),(33,0,'2026-09-23 01:09:47','2026-09-23 01:09:47','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_10.jpg\" alt=\"Phát triển mô hình kinh tế tuần hoàn và tăng trưởng xanh bền vững\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Kinh tế tuần hoàn là giải pháp kinh tế tối ưu giúp vừa gia tăng lợi nhuận doanh nghiệp vừa bảo vệ nguồn tài nguyên thiên nhiên đang cạn kệt.</p>\n<h2>1. Nguyên lý Thiết kế không rác thải</h2>\n<p>Các sản phẩm từ bao bì, thiết bị điện tử đến may mặc được thiết kế ngay từ đầu để dễ dàng tháo dỡ, tái chế và tái sử dụng sau chu kỳ vòng đời.</p>\n<h2>2. Bộ tiêu chuẩn ESG trong thu hút vốn đầu tư</h2>\n<p>Các quỹ đầu tư lớn trên thế giới hiện nay chỉ ưu tiên rót vốn vào các doanh nghiệp đáp ứng tốt bộ tiêu chí Môi trường, Xã hội và Quản trị (ESG).</p>','Phát triển mô hình kinh tế tuần hoàn và tăng trưởng xanh bền vững','Mô hình kinh tế tuần hoàn tái sử dụng tài nguyên giúp các doanh nghiệp vừa cắt giảm chi phí sản xuất vừa đạt chứng nhận ESG.','publish','open','open','','phat-trien-mo-hinh-kinh-te-tuan-hoan-va-tang-truong-xanh-ben-vung','','','2026-09-23 01:13:36','2026-09-23 01:13:36','',0,'http://wordpress.local/?p=33',0,'post','',4),(34,0,'2026-09-23 01:13:18','2026-09-23 01:13:18','','sample_featured_1.jpg','','inherit','open','closed','','sample_featured_1-jpg','','','2026-09-23 01:13:18','2026-09-23 01:13:18','',0,'http://wordpress.local/?attachment_id=34',0,'attachment','image/jpeg',0),(35,0,'2026-09-23 01:13:19','2026-09-23 01:13:19','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_1.jpg\" alt=\"Chính sách phát triển kinh tế xã hội giai đoạn mới và tầm nhìn chiến lược\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Trong bối cảnh hội nhập quốc tế ngày càng sâu rộng, việc hoạch định và thực thi các chính sách phát triển kinh tế xã hội giai đoạn mới đóng vai trò then chốt đối với sự phát triển bền vững của quốc gia.</p>\n<h2>1. Đột phá trong cải cách hành chính và tư duy quản lý</h2>\n<p>Chính phủ đã ban hành nhiều nghị quyết quan trọng nhằm tháo gỡ khó khăn cho doanh nghiệp, cắt giảm các thủ tục rườm rà và đẩy mạnh ứng dụng công nghệ thông tin trong cung cấp dịch vụ công trực tuyến. Việc chuyển đổi từ phương thức quản lý truyền thống sang quản trị hiện đại dựa trên dữ liệu đã giúp tiết kiệm hàng ngàn tỷ đồng và thời gian cho xã hội.</p>\n<h2>2. Phát triển nguồn nhân lực chất lượng cao</h2>\n<p>Nguồn nhân lực được xác định là động lực trung tâm của sự phát triển. Các chính sách ưu đãi đối với giáo dục, đào tạo nghề và thu hút nhân tài trong và ngoài nước đang được triển khai mạnh mẽ.</p>','Chính sách phát triển kinh tế xã hội giai đoạn mới và tầm nhìn chiến lược','Các định hướng chính sách phát triển kinh tế xã hội giai đoạn mới mang tính đột phá, trọng tâm cải cách hành chính và đổi mới mô hình tăng trưởng.','inherit','closed','closed','','24-revision-v1','','','2026-09-23 01:13:19','2026-09-23 01:13:19','',24,'http://wordpress.local/?p=35',0,'revision','',0),(36,0,'2026-09-23 01:13:20','2026-09-23 01:13:20','','sample_featured_2.jpg','','inherit','open','closed','','sample_featured_2-jpg','','','2026-09-23 01:13:20','2026-09-23 01:13:20','',0,'http://wordpress.local/?attachment_id=36',0,'attachment','image/jpeg',0),(37,0,'2026-09-23 01:13:21','2026-09-23 01:13:21','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_2.jpg\" alt=\"Đổi mới công tác quản lý đô thị và quy hoạch hạ tầng giao thông hiện đại\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Quản lý đô thị và quy hoạch hạ tầng giao thông là một trong những nhiệm vụ trọng tâm được các cấp chính quyền đặc biệt quan tâm trong thời kỳ công nghiệp hóa, hiện đại hóa.</p>\n<h2>1. Xây dựng các đô thị thông minh</h2>\n<p>Ứng dụng công nghệ Internet of Things (IoT) và trí tuệ nhân tạo trong giám sát giao thông, quản lý năng lượng và xử lý rác thải đang trở thành chuẩn mực mới tại các đại đô thị. Hệ thống trung tâm điều hành thông minh giúp chính quyền phản ứng nhanh chóng với các sự cố đô thị.</p>\n<h2>2. Đầu tư mạng lưới giao thông công cộng hiện đại</h2>\n<p>Các dự án đường sắt đô thị, xe buýt điện thông minh và hệ thống cầu vượt kết nối liên vùng đang được tăng tốc hoàn thành. Điều này không chỉ giảm thiểu ùn tắc giao thông mà còn giảm lượng khí thải carbon phát thải ra môi trường.</p>','Đổi mới công tác quản lý đô thị và quy hoạch hạ tầng giao thông hiện đại','Tập trung phát triển các đô thị thông minh, kết nối mạng lưới giao thông công cộng đường sắt đô thị và giảm ùn tắc.','inherit','closed','closed','','25-revision-v1','','','2026-09-23 01:13:21','2026-09-23 01:13:21','',25,'http://wordpress.local/?p=37',0,'revision','',0),(38,0,'2026-09-23 01:13:22','2026-09-23 01:13:22','','sample_featured_3.jpg','','inherit','open','closed','','sample_featured_3-jpg','','','2026-09-23 01:13:22','2026-09-23 01:13:22','',0,'http://wordpress.local/?attachment_id=38',0,'attachment','image/jpeg',0),(39,0,'2026-09-23 01:13:23','2026-09-23 01:13:23','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_3.jpg\" alt=\"Tăng cường hợp tác quốc tế và chủ động hội nhập ngoại giao đa phương\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Công tác đối ngoại và hợp tác quốc tế ngày càng khẳng định vị thế và đóng góp tích cực vào công cuộc phát triển chung của đất nước.</p>\n<h2>1. Đa phương hóa, đa dạng hóa quan hệ quốc tế</h2>\n<p>Việc ký kết và thực thi hiệu quả các hiệp định thương mại tự do thế hệ mới (FTA) đã mở ra không gian phát triển rộng lớn cho hàng hóa và dịch vụ trong nước vươn ra thị trường toàn cầu.</p>\n<h2>2. Thu hút dòng vốn đầu tư nước ngoài có chọn lọc</h2>\n<p>Chính sách thu hút FDI chuyển dịch mạnh mẽ từ số lượng sang chất lượng, ưu tiên các dự án áp dụng công nghệ cao, thân thiện môi trường và có tính lan tỏa lớn đối với nền kinh tế nội địa.</p>','Tăng cường hợp tác quốc tế và chủ động hội nhập ngoại giao đa phương','Ngoại giao đa phương đóng vai trò cầu nối thúc đẩy thương mại quốc tế, thu hút dòng vốn đầu tư FDI và nâng cao uy tín quốc gia.','inherit','closed','closed','','26-revision-v1','','','2026-09-23 01:13:23','2026-09-23 01:13:23','',26,'http://wordpress.local/?p=39',0,'revision','',0),(40,0,'2026-09-23 01:13:24','2026-09-23 01:13:24','','sample_featured_4.jpg','','inherit','open','closed','','sample_featured_4-jpg','','','2026-09-23 01:13:24','2026-09-23 01:13:24','',0,'http://wordpress.local/?attachment_id=40',0,'attachment','image/jpeg',0),(41,0,'2026-09-23 01:13:25','2026-09-23 01:13:25','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_4.jpg\" alt=\"Trí tuệ nhân tạo đang thay đổi cách con người nghiên cứu khoa học\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Sự bùng nổ của Trí tuệ Nhân tạo (AI) và Học máy (Machine Learning) đang tạo ra một cuộc cách mạng sâu sắc trong cách thức các nhà khoa học thực hiện nghiên cứu.</p>\n<h2>1. Tăng tốc phân tích dữ liệu siêu khổng lồ</h2>\n<p>Trước đây, việc phân tích hàng tỷ chuỗi ADN hoặc dữ liệu thiên văn học có thể mất hàng thập kỷ. Ngày nay, với các mô hình học sâu hiện đại, AI có thể xử lý và phát hiện ra các quy luật ẩn giấu chỉ trong vài giờ đồng hồ.</p>\n<h2>2. Dự đoán cấu trúc sinh học và phân tử</h2>\n<p>Các công cụ như AlphaFold đã giải quyết được thách thức 50 năm qua của sinh học hiện đại bằng cách dự đoán chính xác cấu trúc 3D của gần như tất cả các protein đã biết.</p>','Trí tuệ nhân tạo đang thay đổi cách con người nghiên cứu khoa học','Trí tuệ nhân tạo (AI) giúp tăng tốc độ phát hiện thuốc mới, dự đoán cấu trúc protein và tối ưu hóa các thí nghiệm phức tạp.','inherit','closed','closed','','6-revision-v1','','','2026-09-23 01:13:25','2026-09-23 01:13:25','',6,'http://wordpress.local/?p=41',0,'revision','',0),(42,0,'2026-09-23 01:13:26','2026-09-23 01:13:26','','sample_featured_5.jpg','','inherit','open','closed','','sample_featured_5-jpg','','','2026-09-23 01:13:26','2026-09-23 01:13:26','',0,'http://wordpress.local/?attachment_id=42',0,'attachment','image/jpeg',0),(43,0,'2026-09-23 01:13:27','2026-09-23 01:13:27','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_5.jpg\" alt=\"Ứng dụng công nghệ năng lượng xanh và giải pháp pin lưu trữ thế hệ mới\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Chuyển dịch sang năng lượng tái tạo là con đường duy nhất để loài người đối phó với biến đổi khí hậu toàn cầu.</p>\n<h2>1. Đột phá từ công nghệ pin thể rắn</h2>\n<p>Pin thể rắn thế hệ mới mang lại mật độ năng lượng cao gấp đôi so với pin Lithium-ion truyền thống, đồng thời rút ngắn thời gian sạc xuống còn vài phút và loại bỏ hoàn toàn nguy cơ cháy nổ.</p>\n<h2>2. Tích hợp hệ thống lưới điện thông minh</h2>\n<p>Nhờ vào các hệ thống pin lưu trữ quy mô lớn kết hợp với AI dự báo thời tiết, các trang trại điện gió và điện mặt trời có thể cung cấp nguồn điện ổn định 24/7 mà không bị gián đoạn.</p>','Ứng dụng công nghệ năng lượng xanh và giải pháp pin lưu trữ thế hệ mới','Công nghệ pin thể rắn và giải pháp tích trữ năng lượng mặt trời giúp giải bài toán biến đổi khí hậu.','inherit','closed','closed','','28-revision-v1','','','2026-09-23 01:13:27','2026-09-23 01:13:27','',28,'http://wordpress.local/?p=43',0,'revision','',0),(44,0,'2026-09-23 01:13:28','2026-09-23 01:13:28','','sample_featured_6.jpg','','inherit','open','closed','','sample_featured_6-jpg','','','2026-09-23 01:13:28','2026-09-23 01:13:28','',0,'http://wordpress.local/?attachment_id=44',0,'attachment','image/jpeg',0),(45,0,'2026-09-23 01:13:28','2026-09-23 01:13:28','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_6.jpg\" alt=\"Khám phá mới về vũ trụ, lỗ đen và sóng hấp dẫn liên ngân hà\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Vũ trụ bao la luôn chứa đựng những bí ẩn thách thức trí tuệ con người, và những phát hiện gần đây đang viết lại sách giáo khoa vật lý thiên văn.</p>\n<h2>1. Mắt thần James Webb và những thiên hà cổ đại</h2>\n<p>Kính thiên văn James Webb đã quan sát được những ánh sáng cổ xưa nhất hành tinh từ 13.5 tỷ năm trước, giúp các nhà vật lý hiểu rõ hơn về giai đoạn khởi đầu của vũ trụ.</p>\n<h2>2. Đo lường sóng hấp dẫn từ các vụ va chạm lỗ đen</h2>\n<p>Các đài quan sát LIGO và Virgo tiếp tục ghi nhận hàng loạt tín hiệu sóng hấp dẫn – những gợn sóng trong không-thời gian sinh ra từ sự hợp nhất giữa các lỗ đen siêu nặng.</p>','Khám phá mới về vũ trụ, lỗ đen và sóng hấp dẫn liên ngân hà','Kính thiên văn không gian James Webb hé lộ những hình ảnh đầu tiên về các thiên hà cổ đại hình thành ngay sau Vụ Nổ Lớn Big Bang.','inherit','closed','closed','','29-revision-v1','','','2026-09-23 01:13:28','2026-09-23 01:13:28','',29,'http://wordpress.local/?p=45',0,'revision','',0),(46,0,'2026-09-23 01:13:30','2026-09-23 01:13:30','','sample_featured_7.jpg','','inherit','open','closed','','sample_featured_7-jpg','','','2026-09-23 01:13:30','2026-09-23 01:13:30','',0,'http://wordpress.local/?attachment_id=46',0,'attachment','image/jpeg',0),(47,0,'2026-09-23 01:13:30','2026-09-23 01:13:30','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_7.jpg\" alt=\"Đột phá trong công nghệ sinh học y học tái tạo và chỉnh sửa gen CRISPR\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Y học tái tạo và công nghệ gen đang mở ra kỷ nguyên y học cá thể hóa, nơi căn bệnh được chữa trị dựa trên mã gen riêng của từng bệnh nhân.</p>\n<h2>1. Công nghệ CRISPR-Cas9 trong điều trị y học</h2>\n<p>Các thử nghiệm lâm sàng sử dụng kéo sinh học CRISPR để sửa đổi mã gen lỗi đã chữa khỏi thành công bệnh hồng cầu hình liềm và mở ra hy vọng diệt trừ tận gốc virus HIV.</p>\n<h2>2. In 3D sinh học và nội tạng nhân tạo</h2>\n<p>Công nghệ in 3D tế bào sống đang tiến gần hơn đến việc sản xuất các mô cơ tim, màng da và mạch máu nhân tạo phục vụ ghép tạng mà không bị thải ghép.</p>','Đột phá trong công nghệ sinh học y học tái tạo và chỉnh sửa gen CRISPR','Kỹ thuật chỉnh sửa gen chính xác cao đang thử nghiệm điều trị các bệnh di truyền và ung thư tận gốc.','inherit','closed','closed','','30-revision-v1','','','2026-09-23 01:13:30','2026-09-23 01:13:30','',30,'http://wordpress.local/?p=47',0,'revision','',0),(48,0,'2026-09-23 01:13:32','2026-09-23 01:13:32','','sample_featured_8.jpg','','inherit','open','closed','','sample_featured_8-jpg','','','2026-09-23 01:13:32','2026-09-23 01:13:32','',0,'http://wordpress.local/?attachment_id=48',0,'attachment','image/jpeg',0),(49,0,'2026-09-23 01:13:32','2026-09-23 01:13:32','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_8.jpg\" alt=\"Xu hướng thương mại điện tử xuyên biên giới và chuyển đổi số doanh nghiệp\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Thương mại điện tử không còn là xu hướng chốc lát mà đã trở thành trụ cột quan trọng của nền kinh tế số toàn cầu.</p>\n<h2>1. Sự lên ngôi của bán hàng Omni-channel</h2>\n<p>Khách hàng ngày nay đòi hỏi trải nghiệm mua sắm liền mạch từ trực tuyến đến trực tiếp. Các doanh nghiệp tiên phong đang áp dụng AI để cá nhân hóa đề xuất sản phẩm cho từng người dùng.</p>\n<h2>2. Logistics thông minh và tự động hóa kho hàng</h2>\n<p>Hệ thống tự động hóa kho bãi sử dụng robot giao hàng và thuật toán định tuyến thông minh giúp giao hàng trong ngày với chi phí thấp hơn 30%.</p>','Xu hướng thương mại điện tử xuyên biên giới và chuyển đổi số doanh nghiệp','Thương mại điện tử phát triển thần tốc thúc đẩy các chuỗi cung ứng tối ưu hóa bằng trí tuệ nhân tạo và dữ liệu lớn.','inherit','closed','closed','','31-revision-v1','','','2026-09-23 01:13:32','2026-09-23 01:13:32','',31,'http://wordpress.local/?p=49',0,'revision','',0),(50,0,'2026-09-23 01:13:34','2026-09-23 01:13:34','','sample_featured_9.jpg','','inherit','open','closed','','sample_featured_9-jpg','','','2026-09-23 01:13:34','2026-09-23 01:13:34','',0,'http://wordpress.local/?attachment_id=50',0,'attachment','image/jpeg',0),(51,0,'2026-09-23 01:13:34','2026-09-23 01:13:34','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_9.jpg\" alt=\"Thị trường tài chính toàn cầu, xu hướng lãi suất và các thách thức lớn\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Nền kinh tế thế giới đang trải qua giai đoạn biến động đầy thách thức với lạm phát, điều chỉnh chính sách lãi suất và sự dịch chuyển của các dòng vốn đầu tư.</p>\n<h2>1. Tác động từ chính sách tiền tệ thắt chặt</h2>\n<p>Các chính sách điều chỉnh lãi suất ngân hàng nhằm kiểm soát lạm phát đã ảnh hưởng đáng kể đến chi phí vốn của doanh nghiệp và hoạt động kinh doanh bất động sản.</p>\n<h2>2. Sự bùng nổ của tài chính công nghệ (Fintech)</h2>\n<p>Các ứng dụng thanh toán không tiền mặt, ngân hàng số và tài sản mã hóa đang thay đổi thói quen quản lý tài chính cá nhân của thế hệ trẻ.</p>','Thị trường tài chính toàn cầu, xu hướng lãi suất và các thách thức lớn','Phân tích biến động tỷ giá, chính sách tiền tệ của các Ngân hàng Trung ương lớn và định hướng đầu tư an toàn.','inherit','closed','closed','','32-revision-v1','','','2026-09-23 01:13:34','2026-09-23 01:13:34','',32,'http://wordpress.local/?p=51',0,'revision','',0),(52,0,'2026-09-23 01:13:36','2026-09-23 01:13:36','','sample_featured_10.jpg','','inherit','open','closed','','sample_featured_10-jpg','','','2026-09-23 01:13:36','2026-09-23 01:13:36','',0,'http://wordpress.local/?attachment_id=52',0,'attachment','image/jpeg',0),(53,0,'2026-09-23 01:13:36','2026-09-23 01:13:36','<p><img src=\"http://wordpress.local/wp-content/uploads/2026/09/sample_featured_10.jpg\" alt=\"Phát triển mô hình kinh tế tuần hoàn và tăng trưởng xanh bền vững\" style=\"width:100%;height:auto;border-radius:6px;margin:20px 0\" /></p>\n<p class=\"sapo\">Kinh tế tuần hoàn là giải pháp kinh tế tối ưu giúp vừa gia tăng lợi nhuận doanh nghiệp vừa bảo vệ nguồn tài nguyên thiên nhiên đang cạn kệt.</p>\n<h2>1. Nguyên lý Thiết kế không rác thải</h2>\n<p>Các sản phẩm từ bao bì, thiết bị điện tử đến may mặc được thiết kế ngay từ đầu để dễ dàng tháo dỡ, tái chế và tái sử dụng sau chu kỳ vòng đời.</p>\n<h2>2. Bộ tiêu chuẩn ESG trong thu hút vốn đầu tư</h2>\n<p>Các quỹ đầu tư lớn trên thế giới hiện nay chỉ ưu tiên rót vốn vào các doanh nghiệp đáp ứng tốt bộ tiêu chí Môi trường, Xã hội và Quản trị (ESG).</p>','Phát triển mô hình kinh tế tuần hoàn và tăng trưởng xanh bền vững','Mô hình kinh tế tuần hoàn tái sử dụng tài nguyên giúp các doanh nghiệp vừa cắt giảm chi phí sản xuất vừa đạt chứng nhận ESG.','inherit','closed','closed','','33-revision-v1','','','2026-09-23 01:13:36','2026-09-23 01:13:36','',33,'http://wordpress.local/?p=53',0,'revision','',0),(54,0,'2026-09-23 01:20:11','2026-09-23 01:20:11','Trí tuệ nhân tạo đang được ứng dụng trong nhiều lĩnh vực nghiên cứu khoa học, từ phân tích dữ liệu, mô phỏng đến hỗ trợ các phát minh mới. Công nghệ này giúp tối ưu hóa thời gian và gia tăng độ chính xác trong các nghiên cứu phức tạp.','Trí tuệ nhân tạo đang thay đổi cách con người nghiên cứu khoa học','Trí tuệ nhân tạo (AI) giúp tăng tốc độ phát hiện thuốc mới, dự đoán cấu trúc protein và tối ưu hóa các thí nghiệm phức tạp.','inherit','closed','closed','','6-revision-v1','','','2026-09-23 01:20:11','2026-09-23 01:20:11','',6,'http://wordpress.local/?p=54',0,'revision','',0),(55,1,'2026-09-23 01:34:37','2026-09-23 01:34:37','','Kinh tế tuần hoàn','','inherit','open','closed','','kinh-te-tuan-hoan','','','2026-09-23 01:34:37','2026-09-23 01:34:37','',33,'http://wordpress.local/wp-content/uploads/2026/09/kinh_te_tuan_hoan.svg',0,'attachment','image/svg+xml',0),(56,1,'2026-09-23 01:34:37','2026-09-23 01:34:37','','Tài chính toàn cầu','','inherit','open','closed','','tai-chinh-toan-cau','','','2026-09-23 01:34:37','2026-09-23 01:34:37','',32,'http://wordpress.local/wp-content/uploads/2026/09/tai_chinh_toan_cau.svg',0,'attachment','image/svg+xml',0),(57,1,'2026-09-23 01:34:38','2026-09-23 01:34:38','','Thương mại điện tử','','inherit','open','closed','','thuong-mai-dien-tu','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',31,'http://wordpress.local/wp-content/uploads/2026/09/thuong_mai_dien_tu.svg',0,'attachment','image/svg+xml',0),(58,1,'2026-09-23 01:34:38','2026-09-23 01:34:38','','Công nghệ sinh học','','inherit','open','closed','','cong-nghe-sinh-hoc','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',30,'http://wordpress.local/wp-content/uploads/2026/09/cong_nghe_sinh_hoc.svg',0,'attachment','image/svg+xml',0),(59,1,'2026-09-23 01:34:38','2026-09-23 01:34:38','','Khám phá vũ trụ','','inherit','open','closed','','kham-pha-vu-tru','','','2026-09-23 01:34:38','2026-09-23 01:34:38','',29,'http://wordpress.local/wp-content/uploads/2026/09/kham_pha_vu_tru.svg',0,'attachment','image/svg+xml',0),(60,1,'2026-09-23 01:34:38','2026-09-23 01:34:38','','Năng lượng xanh','','inherit','open','